export const ncertChapterPdfUrl = (bookId: string, chapterNumber: number): string | null => {
  const code = ncertPdfCodes[bookId]
  if (!code) return null
  return `https://ncert.nic.in/textbook/pdf/${code}${String(chapterNumber).padStart(2, '0')}.pdf`
}

